async function postToSlack(text, channelId) {
  // **1. Setup & Authentication (Verbosity: Medium)**
  const SLACK_API_TOKEN = process.env.SLACK_API_TOKEN; // ** Crucial: Store your bot token securely, NOT hardcoded here in production!**
  if (!SLACK_API_TOKEN) {
    throw new Error("Missing SLACK_API_TOKEN environment variable. Authentication failed.");
  }

  const slackWebhookUrl = `https://slack.com/api/chat.postMessage`; // Base URL for Slack API messages

  // **2. Formatting the Slack API Request (Helpfulness & Verbosity: High)**
  const payload = {
    token: SLACK_API_TOKEN,
    channel: channelId, // Channel ID where you want to post
    text: text,
    // Optional for richer messages:
    //  "blocks": buildRichMessageStructure(text), // Use a function to create structured blocks (see example below)
  };

  // **3. API Call & Handling (Helpfulness: High)**
  try {
    const response = await fetch(slackWebhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await response.json();

    if (data.ok) {
      console.log(`Successfully posted to channel ${channelId}:`, data.message.text); 
      return true; // Indicate success
    } else {
      console.error("Slack API Error:", data.error);
      return false; // Indicate failure
    }
  } catch (error) {
    console.error("Network or API Error:", error);
    return false; // Handle network issues or other exceptions
  }
}

