#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: 0th element is the first input 'a'
    if (n == 1) return b;  // Base case: 1st element is the second input 'b'
    return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> start1 >> start2)) {  // Input validation: Check for numeric input
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Clear error state
        cerr << "Invalid input. Please enter two integers: ";
    }

    cout << "Enter the desired sequence length: ";
    while (!(cin >> count) || count <= 0) { // Input validation: Positive integer check
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Enter a positive integer: ";
    }

    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 0; i < count; ++i) {
        int nextFib = fibonacci(start1, start2, i);
        cout << nextFib << " ";  // Output each element with comma and space separation
        start1 = start2;       // Update for next iteration
        start2 = nextFib;
    }
    cout << endl;

    return 0;
}
